        "html": "<table class=\"va-guide-grid va-guide-grid--wrap\">\n<thead><tr><th scope=\"col\">Ce que vous constatez</th><th scope=\"col\">La cause</th><th scope=\"col\">La solution</th></tr></thead>\n<tbody><tr><td data-label=\"Ce que vous constatez\">La mousse ne prend pas de volume</td><td data-label=\"La cause\">Aquafaba trop chaud ou matériel gras</td><td data-label=\"La solution\">Réfrigérez à {pavlova_chill} °C et utilisez du matériel propre</td></tr>\n<tr><td data-label=\"Ce que vous constatez\">La coque se fissure au refroidissement</td><td data-label=\"La cause\">Refroidissement trop rapide</td><td data-label=\"La solution\">Laissez refroidir dans le four éteint, porte entrouverte</td></tr>\n<tr><td data-label=\"Ce que vous constatez\">Le centre reste entièrement mou</td><td data-label=\"La cause\">Séchage insuffisant</td><td data-label=\"La solution\">Respectez les {pavlova_hours} heures à {pavlova_oven} °C</td></tr>\n<tr><td data-label=\"Ce que vous constatez\">Le centre sèche complètement</td><td data-label=\"La cause\">Amidon et acide omis, ou séchage excessif</td><td data-label=\"La solution\">Incorporez-les ; sortez la base quand le centre reste souple</td></tr>\n<tr><td data-label=\"Ce que vous constatez\">La base ramollit après le montage</td><td data-label=\"La cause\">Garniture ajoutée trop tôt</td><td data-label=\"La solution\">Ajoutez la crème et les fruits au service</td></tr></tbody>\n</table>"
